import java.util.ArrayList;
import java.util.List;

class Person {
    private String name;

    Person(String name) {
        this.name = name;
    }

    String getName() { return name; }

    String intro() {
        return "本喵叫 " + name;
    }
}

class Student extends Person {
    private int score;

    Student(String name, int score) {
        super(name);
        this.score = score;
    }

    int getScore() { return score; }

    @Override
    String intro() {
        return super.intro() + "，考了 " + score + " 分";
    }
}

public class Main {
    public static void main(String[] args) {
        List<Person> mingdan = new ArrayList<>();
        mingdan.add(new Person("大肥鱼"));
        mingdan.add(new Student("小橘", 92));
        mingdan.add(new Student("狸花", 78));
        mingdan.add(new Student("小虎", 88));
        for (Person p : mingdan) {
            System.out.println(p.intro());
        }
        int sum = 0;
        int n = 0;
        for (Person p : mingdan) {
            if (p instanceof Student) {
                Student s = (Student) p;
                sum += s.getScore();
                n++;
            }
        }
        System.out.println("学生 " + n + " 只，平均 " + (sum / n) + " 分");
    }
}
